contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address caller, address newOwner) public {
        require(caller != address(0) && newOwner != address(0));

        // caller must be the current owner for setOwner to succeed
        require(caller == c.owner());

        bool returned = c.setOwner(newOwner); if (__ESBMC_reverted()) return;
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;

        assert(returned == true && afterOwner == newOwner);
    }
}

